  "extra": "<section><h2>NIOSH 시험 결과 한눈에 보기</h2><div class=\"table-scroll\"><table><thead><tr><th>조건</th><th>기준 장비와의 차이</th><th>출처</th></tr></thead><tbody><tr><td>내장 마이크, 가장 잘 맞은 앱 (A특성)</td><td>평균 0.5dBA</td><td>2014년 논문</td></tr><tr><td>내장 마이크, ±2dBA 안에 든 앱</td><td>iOS 앱 10개 중 3개</td><td>2014년 논문</td></tr><tr><td>내장 마이크, 가장 안 맞은 앱 (A특성)</td><td>평균 약 13dBA</td><td>2014년 논문</td></tr><tr><td>기기별 평균 (같은 앱 10개, A특성)</td><td>0.7~5.4dBA</td><td>2014년 논문</td></tr><tr><td>교정한 외부 마이크 + 앱 4개</td><td>±1dB 안쪽</td><td>2016년 논문</td></tr><tr><td>NIOSH SLM 앱 (iOS)</td><td>±2dBA</td><td>CDC 안내 페이지</td></tr><tr><td>전문 소음계 허용 오차 (ANSI S1.4)</td><td>1급 약 ±1.5dB, 2급 약 ±2.3dB</td><td>2014년 논문에 인용</td></tr></tbody></table></div><p>모두 잔향실에서 65~95dB 핑크 노이즈로 시험한 값이에요. 2014년 시험의 앱은 교정하지 않은 상태였고, 차이는 부호를 떼고 크기만 적었어요.</p></section>",
