    "extra": "<section><h2>WHO 환경소음 가이드라인(2018) 권고값 한눈에 보기</h2><div class=\"table-scroll\"><table><thead><tr><th>소음원</th><th>평균 (Lden)</th><th>밤 (Lnight)</th><th>권고 강도</th><th>숫자를 정한 근거</th></tr></thead><tbody><tr><td>도로 교통</td><td>53dB</td><td>45dB</td><td>강함</td><td>53.3dB에서 매우 성가심 10%, 45.4dB에서 심한 수면 방해 3%</td></tr><tr><td>철도</td><td>54dB</td><td>44dB</td><td>강함</td><td>53.7dB에서 매우 성가심 10%, 밤은 43.7dB를 반올림</td></tr><tr><td>항공기</td><td>45dB</td><td>40dB</td><td>강함</td><td>45.4dB에서 매우 성가심 10%, 40dB에서 심한 수면 방해 11%</td></tr><tr><td>풍력발전기</td><td>45dB</td><td>권고 없음</td><td>조건부</td><td>밤은 근거의 질이 낮아 권고하지 않음</td></tr><tr><td>여가 소음 전체</td><td colspan=\"2\">1년 평균 LAeq,24h 70dB</td><td>조건부</td><td>청력 손상 위험</td></tr></tbody></table></div><p>Lden·Lnight는 소리를 가장 많이 받는 건물 외벽 바깥에서 본 1년 평균이에요. Lden은 저녁에 5dB, 밤에 10dB를 더해 계산해요. 출처: WHO 유럽지역사무소 환경소음 가이드라인(2018).</p></section>",
