    "title": "구급차가 지나가면 사이렌이 왜 낮아질까: 도플러 효과를 숫자로 읽기",
    "desc": "다가오는 사이렌은 높게, 지나간 뒤에는 낮게 들리는 이유가 궁금하다면 답은 파장이에요. 사이렌 자체는 그대로인데 내 귀에 도착하는 파장이 짧아졌다 길어지는 거예요. 식과 계산 예시, 초음파 혈류 검사와 소닉붐까지 공식 자료로 정리했어요.",
    "time": "7분",
    "published": "2026-11-21",
    "modified": "2026-11-21",
