    "extra": "<section><h2>보청기와 소리 증폭기 한눈에 비교</h2><div class=\"table-scroll\"><table><thead><tr><th>구분</th><th>처방 보청기</th><th>OTC 보청기(미국)</th><th>개인용 소리 증폭기(PSAP)</th></tr></thead><tbody><tr><td>대상</td><td>난청이 있는 사람, 심하거나 복잡한 난청 포함</td><td>경도~중등도 난청을 스스로 느끼는 18세 이상 성인</td><td>난청이 없는 사람</td></tr><tr><td>구입 방법</td><td>청각 전문가를 통해 맞춤·조정</td><td>매장·온라인에서 바로 구입, 스스로 맞춤</td><td>처방이나 진찰 없이 구입</td></tr><tr><td>미국 FDA 규제</td><td>의료기기</td><td>의료기기 (2022년 8월 규정 확정)</td><td>의료기기 아님</td></tr><tr><td>맞지 않는 경우</td><td>속귀 손상이 너무 커서 증폭해도 신호로 바뀌지 않을 때</td><td>아동, 고도 이상 난청, 조용한 곳에서도 대화가 어려울 때</td><td>난청을 보완하려는 용도</td></tr></tbody></table></div><p>국내에서 식품의약품안전처는 보청기를 소리를 증폭해 난청인의 청음을 보조하는 의료기기로 설명해요. OTC 보청기는 미국 제도라서 국내 판매 방식과 다를 수 있어요. 출처: NIDCD, 식품의약품안전처.</p></section>",
