        "NIDCD는 개인용 소리 증폭기(PSAP)를 난청이 없는 사람이 특정 상황에서 쓰는 제품으로 설명하고, 미국 FDA도 이를 의료기기로 규제하지 않아요. 듣기가 불편하다면 먼저 청력검사로 난청 여부와 정도를 확인하는 편이 맞아요."
