    "title": "소리는 1초에 몇 m를 갈까: 기온이 1℃ 오르면 초속 0.6m 빨라져요",
    "desc": "소리 속도가 왜 340m/s 하나로 정해져 있지 않은지 궁금하다면, 답은 공기 온도예요. 기온별 속도, 번개까지 거리 세는 법, 물과 쇠에서의 속도까지 공식 자료로 정리했어요.",
    "time": "7분",
