    "desc": "60dB 소리 두 개를 합쳐도 120dB이 되지 않고 약 63dB이 돼요. 데시벨이 로그 단위라서 그런데, 3dB·10dB 차이가 무슨 뜻인지와 0dB가 왜 무음이 아닌지 계산과 함께 정리했어요.",
