    "lead": "90dB 기계 옆에 똑같은 기계를 한 대 더 켜면 소음은 몇 dB이 될까요? 180dB이라고 답하기 쉽지만, 미국 산업안전보건청(OSHA) 기술 매뉴얼에 나온 답은 93dB이에요. 데시벨은 길이나 무게처럼 그대로 더할 수 없는 로그 단위예요. 데시벨의 정의, 소리를 합칠 때의 계산, 10dB 차이의 의미를 차례로 계산 예시와 함께 살펴볼게요.",
