    "extra": "<section><h2>데시벨 차이를 비율로 바꿔 읽는 표</h2><div class=\"table-scroll\"><table><thead><tr><th>dB 차이</th><th>세기(에너지) 비율</th><th>음압 비율</th><th>참고</th></tr></thead><tbody><tr><td>+1dB</td><td>약 1.26배</td><td>약 1.12배</td><td>정상 청력이 알아차리는 가장 작은 차이 수준(작은 소리 기준, HyperPhysics)</td></tr><tr><td>+3dB</td><td>약 2배</td><td>약 1.41배</td><td>같은 크기 소리 두 개를 합칠 때(OSHA)</td></tr><tr><td>+6dB</td><td>약 4배</td><td>약 2배</td><td>같은 크기 소리 네 개를 합칠 때</td></tr><tr><td>+10dB</td><td>10배</td><td>약 3.16배</td><td>대략 두 배 크게 들림(HyperPhysics, 국가소음정보시스템)</td></tr><tr><td>+20dB</td><td>100배</td><td>10배</td><td>—</td></tr></tbody></table></div><p>세기 비율과 음압 비율은 10^(차이/10), 10^(차이/20)으로 구한 계산값이에요. 귀가 느끼는 크기는 주파수와 사람에 따라 달라서 ‘참고’ 칸은 어림 기준으로만 보세요.</p></section>",
