    "desc": "높은 소리와 낮은 소리는 공기가 1초에 몇 번 떨리느냐로 갈려요. Hz 읽는 법과 파장, 사람이 듣는 대략 20Hz~20kHz 범위, 나이가 들면 고음부터 줄어드는 청력까지 정리했어요.",
