    "extra": "<section><h2>주파수별 파장 한눈에 보기 (계산 예시)</h2><div class=\"table-scroll\"><table><thead><tr><th>주파수</th><th>파장 (20℃, 344m/s 기준)</th><th>참고</th></tr></thead><tbody><tr><td>20Hz</td><td>17.2m</td><td>사람이 듣는 범위의 아래쪽 끝 근처</td></tr><tr><td>100Hz</td><td>3.44m</td><td>한 옥타브 위는 200Hz</td></tr><tr><td>1,000Hz (1kHz)</td><td>34.4cm</td><td>한 옥타브 위는 2,000Hz</td></tr><tr><td>2,000~5,000Hz</td><td>17.2~6.9cm</td><td>외이도 공명이 키워 주는 대역</td></tr><tr><td>20,000Hz (20kHz)</td><td>1.72cm</td><td>사람이 듣는 범위의 위쪽 끝 근처</td></tr></tbody></table></div><p>파장은 ‘속도 ÷ 주파수’로 계산한 값이에요. 기온이 달라지면 소리 속도가 바뀌어 파장도 조금씩 달라져요. 듣는 범위의 양 끝은 대표값이라 사람과 나이에 따라 달라요.</p></section>",
