    "extra": "<section><h2>상황별로 정리한 공식 안내</h2><div class=\"table-scroll\"><table><thead><tr><th>상황</th><th>공식 출처의 안내</th><th>출처</th></tr></thead><tbody><tr><td>이명이 자주 또는 계속 들림, 점점 심해짐, 잠·집중·기분에 영향</td><td>진료 예약</td><td>NHS</td></tr><tr><td>맥박에 맞춰 뛰는 이명</td><td>빠른 진료. 영상 검사를 할 수 있고, 한쪽만 들리면 CT가 도움이 될 수 있음</td><td>NHS, NIDCD, 국가건강정보포털</td></tr><tr><td>머리를 다친 뒤 생긴 이명</td><td>응급 진료</td><td>NHS</td></tr><tr><td>갑작스러운 청력 저하, 얼굴 근육 약화, 빙빙 도는 어지럼이 함께 있음</td><td>응급 진료</td><td>NHS</td></tr><tr><td>돌발난청·소음난청과 함께 생긴 급성 이명</td><td>원인 평가 후 스테로이드가 효과적일 수 있음</td><td>국가건강정보포털</td></tr><tr><td>3개월 이상 이어지는 이명</td><td>만성 이명으로 분류. 보청기, 소리 치료, 이명 재훈련 치료, 인지행동치료 등으로 관리</td><td>NIDCD, 국가건강정보포털</td></tr></tbody></table></div><p>NHS는 영국의 진료 체계를 기준으로 안내해요. 국내에서는 이비인후과 진료를 받거나, 응급 상황이면 응급실을 이용하세요. 이 표는 진단 기준이 아니에요.</p></section>",
